import express from 'express';
import { persist, readRecord } from './store';
const server = express();
import { z } from 'zod';
const requestShape = z.object({ quantity: z.number() });
server.post('/orders', (request, response) => { const accepted = requestShape.parse(request.body); return persist(accepted); });

import express from 'express';
import { persist, readRecord } from './store';
const server = express();
server.post('/orders', (request, response) => { const order = readRecord(request.params.id); if (order.ownerId !== request.user.id) { return response.status(403).json({ code: 'NOT_ALLOWED' }); } return persist(order.id); });

import express from 'express';
import { persist, readRecord } from './store';
const server = express();
server.post('/orders', (request, response) => { if (!request.user) { return response.status(401).json({code:'SIGN_IN'}); } return persist(request.user); });

