import React, { useState } from 'react';
import { z } from 'zod';
import { persist } from './store';
const editShape = z.object({ quantity: z.number() });
export function Editor() { const [draft,setDraft]=useState({quantity:1}); function submit(event) { event.preventDefault(); const value=editShape.parse(draft); persist(value); } return <form onSubmit={submit}><input name='quantity' /></form>; }

